window.docContents[162].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___3___-Examples/Representations-of-finite-abelian-groups-and-dual-groups/#Chapter4___Example4___3_FiniteAbelianGroups":{"contents":"(1) Finite abelian groups G = \\mathbb{Z}_{n_1} \\times \\cdots \\times \\mathbb{Z}_{n_k}. Let G^\\vee be the set of irreducible representations of G. Every element of G forms a conjugacy class, so |G^\\vee| = |G|. Recall that all irreducible representations over \\mathbb{C} (and algebraically closed fields in general) of commutative algebras and groups are 1-dimensional. Thus, G^\\vee is an abelian group: if \\rho_1, \\rho_2 : G \\to \\mathbb{C}^\\times are irreducible representations, then so are the representations \\rho_1(g)\\rho_2(g) and \\rho_1(g)^{-1}. The group G^\\vee is called the dual group or character group of G.\n\nFor given n \\geq 1, define \\rho : \\mathbb{Z}_n \\to \\mathbb{C}^\\times by \\rho(m) = e^{2\\pi i m/n}. Then \\mathbb{Z}_n^\\vee = \\{\\rho^k : k = 0, \\ldots, n - 1\\}, so \\mathbb{Z}_n^\\vee \\cong \\mathbb{Z}_n. In general,\n\n(G_1 \\times G_2 \\times \\cdots \\times G_n)^\\vee = G_1^\\vee \\times G_2^\\vee \\times \\cdots \\times G_n^\\vee,\nso G^\\vee \\cong G for any finite abelian group G. This isomorphism is, however, noncanonical: the particular decomposition of G as \\mathbb{Z}_{n_1} \\times \\cdots \\times \\mathbb{Z}_{n_k} is not unique as far as which elements of G correspond to \\mathbb{Z}_{n_1}, etc., is concerned. On the other hand, G \\cong (G^\\vee)^\\vee is a canonical isomorphism, given by \\varphi : G \\to (G^\\vee)^\\vee, where \\varphi(g)(\\chi) = \\chi(g).\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.3. Examples\tRepresentations of finite abelian groups and dual groups","header":"Representations of finite abelian groups and dual groups","id":"/4___-Representations-of-finite-groups___-Basic-results/4___3___-Examples/Representations-of-finite-abelian-groups-and-dual-groups/#Chapter4___Example4___3_FiniteAbelianGroups"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Homomorphism-of-quiver-representations/#Chapter2___Definition2___8___10":{"contents":"Definition 2.8.10. Let (V_i, x_h) and (W_i, y_h) be representations of the quiver Q. A homomorphism \\varphi : (V_i) \\longrightarrow (W_i) of quiver representations is a collection of maps \\varphi_i : V_i \\longrightarrow W_i such that y_h \\circ \\varphi_{h'} = \\varphi_{h''} \\circ x_h for all h \\in E.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tHomomorphism of quiver representations","header":"Homomorphism of quiver representations","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Homomorphism-of-quiver-representations/#Chapter2___Definition2___8___10"},"/4___-Representations-of-finite-groups___-Basic-results/4___3___-Examples/Section-4___3___-Examples/#Chapter4___Introduction_4___3":{"contents":"\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.3. Examples\tSection 4.3: Examples","header":"Section 4.3: Examples","id":"/4___-Representations-of-finite-groups___-Basic-results/4___3___-Examples/Section-4___3___-Examples/#Chapter4___Introduction_4___3"}});
